// Simulates a third-party/framework dependency: lives under a literal
// node_modules path, so the scanner must refuse to walk into it —
// framework internals (e.g. Nest's own injector throws) must never leak
// into an endpoint's documented errors. Plain JS on purpose (like real
// compiled lib output).
// eslint-disable-next-line @typescript-eslint/no-require-imports
const { InternalServerErrorException } = require('@nestjs/common');

class FakeFrameworkClient {
  async fetch() {
    throw new InternalServerErrorException('framework blew up');
  }
}

module.exports = { FakeFrameworkClient };
